package com.gwsheridan.worldarchitect.modpack;

import static org.junit.jupiter.api.Assertions.*;
import com.mojang.serialization.JsonOps;
import com.gwsheridan.worldarchitect.spawn.*;
import java.util.*;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.levelgen.WorldOptions;
import org.junit.jupiter.api.Test;

class PackPolicyTest {
    private BundleManifest manifest(){return new BundleManifest(Identifier.parse("wa_test:pack"),"Pack","Modpack project","Builder","1.0.0",BundleManifest.Lock.FULL,new WorldOptions(17,true,false),List.of(),Map.of(),List.of(),List.of("worldarchitect"),false);}
    @Test void newPoliciesUseFormatThreeAndLegacyManifestsRemainFormatOne(){var old=BundleManifest.CODEC.encodeStart(JsonOps.INSTANCE,manifest()).getOrThrow().getAsJsonObject();assertEquals(1,old.get("format").getAsInt());assertFalse(old.has("pack"));var current=manifest().withPack(Optional.of(PackPolicy.DEFAULT));var json=BundleManifest.CODEC.encodeStart(JsonOps.INSTANCE,current).getOrThrow().getAsJsonObject();assertEquals(3,json.get("format").getAsInt());assertEquals(json,BundleManifest.CODEC.encodeStart(JsonOps.INSTANCE,BundleManifest.CODEC.parse(JsonOps.INSTANCE,json).getOrThrow()).getOrThrow());json.addProperty("format",1);assertTrue(BundleManifest.CODEC.parse(JsonOps.INSTANCE,json).error().isPresent());}
    @Test void runtimeScopesDoNotUnlockOtherGroups(){var policy=new PackPolicy(WorldAdministration.Settings.DEFAULT,List.of("protection"));assertTrue(policy.allows(BundleManifest.Lock.PARTIAL,"protection"));assertFalse(policy.allows(BundleManifest.Lock.PARTIAL,"initial"));assertFalse(policy.allows(BundleManifest.Lock.FULL,"protection"));assertTrue(policy.allows(BundleManifest.Lock.UNLOCKED,"initial"));assertTrue(PackPolicy.CODEC.encodeStart(JsonOps.INSTANCE,new PackPolicy(WorldAdministration.Settings.DEFAULT,List.of("unknown"))).error().isPresent());}
    @Test void inheritedRuntimeDefaultsAndScopesCannotBeWeakened(){var parent=manifest().withPack(Optional.of(PackPolicy.DEFAULT));var draft=new PresetStudio.Draft(parent,com.google.gson.JsonParser.parseString("{\"dimensions\":{}}").getAsJsonObject(),Map.of());var inherited=PresetInheritance.capture(draft,"a".repeat(64));var child=new BundleManifest(Identifier.parse("wa_test:child"),"Child","Derived","Builder","1.0.0",BundleManifest.Lock.FULL,parent.options(),List.of(),Map.of(),List.of(),parent.requiredMods(),false,Optional.of(inherited),parent.pack());assertTrue(BundleManifest.CODEC.encodeStart(JsonOps.INSTANCE,child).isSuccess());assertTrue(BundleManifest.CODEC.encodeStart(JsonOps.INSTANCE,child.withPack(Optional.empty())).error().isPresent());var changed=WorldAdministration.Settings.DEFAULT.withProtection(new WorldAdministration.Protection(true,true,true,true,WorldAdministration.Protection.OFF.containerBlocks()));assertTrue(BundleManifest.CODEC.encodeStart(JsonOps.INSTANCE,child.withPack(Optional.of(new PackPolicy(changed,List.of())))).error().isPresent());}
    @Test void metadataCopiesRetainTheirPackPolicy(){var m=manifest().withPack(Optional.of(PackPolicy.DEFAULT));var draft=new PresetStudio.Draft(m,new com.google.gson.JsonObject(),Map.of());var legacyCopy=manifest();assertEquals(m.pack(),draft.withManifest(legacyCopy).manifest().pack());}
    @Test void legacyLockedParentsCannotAcquireSpawnEditsThroughNewRuntimeScopes(){var parent=manifest();var draft=new PresetStudio.Draft(parent,com.google.gson.JsonParser.parseString("{\"dimensions\":{\"minecraft:overworld\":{}}}").getAsJsonObject(),Map.of());var inherited=PresetInheritance.capture(draft,"a".repeat(64));var child=new BundleManifest(Identifier.parse("wa_test:child"),"Child","Derived","Builder","1.0.0",BundleManifest.Lock.PARTIAL,parent.options(),List.of(),Map.of(),List.of(),parent.requiredMods(),false,Optional.of(inherited),Optional.of(new PackPolicy(WorldAdministration.Settings.DEFAULT,List.of("initial"))));assertTrue(BundleManifest.CODEC.encodeStart(JsonOps.INSTANCE,child).error().isPresent());}
}
